"use client";

/**
 * Creature. A small companion that lives in the interface and only ever
 * reports what's happening: idle, busy, done, an error, asleep. Echo by
 * default; your own with one prop.
 *
 * Two forms, by where it lives:
 * - `vector` is the lit, glossy creature, on the page or a card. It breathes,
 *   drifts, blinks and watches the pointer; its moods are directions on the
 *   same springs, so changing one carries on from wherever it is.
 * - `dots` is the same creature on a dot-matrix screen, moving in steps the
 *   way pixels do.
 *
 * Bring your own character (see character.ts): a body path, the whites of
 * its eyes and its pupils, or rows of text for the dots. Echo supplies the
 * materials, so any character relights with the theme.
 *
 * Decorative by default. Where it carries meaning, the words beside it say
 * so; give it a `label` only when nothing else does.
 */
import { useEffect, useId, useRef, type CSSProperties } from "react";
import { useReducedMotionRef } from "echo-ui-core/tactile";
import { echo, type CreatureCharacter } from "./character";
import { createRig, stillPose, type Rig, type RigMood } from "./rig";
import { gridOf, look, mark, place, screenFor, shut, MARKS, type Dot } from "./dots";
import { rasterize } from "./rasterize";
import { Scope } from "../scope";
import "./creature.css";

export type CreatureMood = "idle" | "busy" | "done" | "error" | "sleep";

export interface CreatureProps {
  /** What it's doing: `idle` (default) watches, `busy` works, `done` hops, `error` is puzzled, `sleep` naps. */
  mood?: CreatureMood;
  /** `vector` (default) on the page; `dots` on a dot-matrix screen of its own. */
  variant?: "vector" | "dots";
  /** Who it is. Default: Echo. */
  character?: CreatureCharacter;
  /** Height in px. Default 96 for `vector`, 120 for `dots`. */
  size?: number;
  /** An accessible name, only when no text nearby says what it shows. */
  label?: string;
  /** A colour of its own, as a hex: a family of creatures, one each (a Scope). */
  accent?: string;
}

const MOODS: Record<CreatureMood, RigMood> = {
  idle: { drift: 2.2, sway: 1.8, pace: 1, lean: 2, breath: 0.03, breathPeriod: 8, lids: 1, look: "follow", blink: [2.6, 6.5] },
  busy: { drift: 1.4, sway: 1.2, pace: 2.4, lean: 0.8, breath: 0.045, breathPeriod: 2.6, lids: 1, look: "follow", blink: [1.8, 4] },
  done: { drift: 0.8, sway: 0.6, pace: 1, lean: 1.4, breath: 0.03, breathPeriod: 6, lids: 1, look: "rest", rest: [0, -0.25], blink: [3, 6] },
  error: { drift: 0.3, sway: 0.3, pace: 0.6, lean: 0, breath: 0.02, breathPeriod: 8, lids: 0.72, look: "rest", rest: [-0.7, 0.55], blink: [5, 9] },
  sleep: { drift: 0.6, sway: 0.5, pace: 0.4, lean: 0, breath: 0.06, breathPeriod: 12, lids: 0.06, look: "rest", rest: [0, 0.3], blink: null },
};

const list = (d: string | readonly string[] | undefined) => (d === undefined ? [] : typeof d === "string" ? [d] : d);

export function Creature({ accent, ...props }: CreatureProps) {
  return accent ? (
    <Scope accent={accent}>
      <Drawn {...props} />
    </Scope>
  ) : (
    <Drawn {...props} />
  );
}

function Drawn({ mood = "idle", variant = "vector", character = echo, size, label }: Omit<CreatureProps, "accent">) {
  const name = label ? { role: "img" as const, "aria-label": label } : { "aria-hidden": true as const };
  const height = size ?? (variant === "dots" ? 120 : 96);
  const [, , vw = 1, vh = 1] = character.viewBox.split(/[\s,]+/).map(Number);
  // Its size and the drawing's proportions, as variables the stylesheet reads.
  const style = { "--creature-size": `${height}px`, "--creature-ratio": (vw / vh).toFixed(4) } as CSSProperties;
  return variant === "dots" ? (
    <div className="echo-creature" data-variant="dots" style={style} {...name}>
      <DotCreature mood={mood} character={character} />
    </div>
  ) : (
    <div className="echo-creature" data-variant="vector" style={style} {...name}>
      <VectorCreature mood={mood} character={character} />
    </div>
  );
}

/* ---------------------------------------------------------------- vector */

function VectorCreature({ mood, character }: { mood: CreatureMood; character: CreatureCharacter }) {
  const uid = useId().replace(/:/g, "");
  const reduced = useReducedMotionRef();
  const wrap = useRef<SVGSVGElement>(null);
  const drift = useRef<SVGGElement>(null);
  const breath = useRef<SVGGElement>(null);
  const lids = useRef<SVGGElement>(null);
  const pupils = useRef<SVGGElement>(null);
  const rig = useRef<Rig | null>(null);
  const drawnFor = useRef(character);
  const eye = [character.origin[0], character.eyeLine] as const;

  // The rig lives as long as the creature does.
  useEffect(
    () => () => {
      rig.current?.destroy();
      rig.current = null;
    },
    [],
  );

  // A new mood is a new direction from wherever it is, never a restart.
  useEffect(() => {
    const next = MOODS[mood];
    const els = { drift: drift.current, breath: breath.current, lids: lids.current, pupils: pupils.current };
    const box = wrap.current?.parentElement;
    if (!box || !els.drift || !els.breath || !els.lids || !els.pupils) return;
    if (reduced.current) {
      stillPose({ drift: els.drift, breath: els.breath, lids: els.lids, pupils: els.pupils }, { eye, mood: next });
      return;
    }
    // Someone else now: their origin and eyes are elsewhere, so a new rig.
    if (rig.current && drawnFor.current !== character) {
      rig.current.destroy();
      rig.current = null;
    }
    drawnFor.current = character;
    if (!rig.current) {
      rig.current = createRig(
        { wrap: box, drift: els.drift, breath: els.breath, lids: els.lids, pupils: els.pupils },
        { origin: character.origin, eye, mood: next },
      );
    } else rig.current.set(next);
    if (mood === "done") rig.current.hop(2);
    if (mood === "error") rig.current.shake();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mood, character]);

  const body = list(character.body);
  return (
    <svg ref={wrap} className="echo-creature__svg" viewBox={character.viewBox} focusable="false">
      <defs>
        <radialGradient id={`${uid}-body`} cx="38%" cy="30%" r="80%">
          <stop offset="0%" className="echo-creature__light" />
          <stop offset="40%" className="echo-creature__mid" />
          <stop offset="100%" className="echo-creature__deep" />
        </radialGradient>
        <radialGradient id={`${uid}-gloss`} cx="34%" cy="22%" r="36%">
          <stop offset="0%" className="echo-creature__gloss-in" />
          <stop offset="100%" className="echo-creature__gloss-out" />
        </radialGradient>
      </defs>
      <g ref={drift}>
        <g ref={breath}>
          {body.map((d, i) => (
            <path key={`b${i}`} d={d} fill={`url(#${uid}-body)`} />
          ))}
          {body.map((d, i) => (
            <path key={`g${i}`} d={d} fill={`url(#${uid}-gloss)`} />
          ))}
          {body.map((d, i) => (
            <path key={`r${i}`} d={d} className="echo-creature__rim" />
          ))}
          <g ref={lids}>
            {(character.eyes ?? []).map((d, i) => (
              <path key={i} d={d} className="echo-creature__eye" />
            ))}
            <g ref={pupils}>
              {(character.pupils ?? []).map((d, i) => (
                <path key={i} d={d} className="echo-creature__pupil" />
              ))}
              {(character.catchLights ?? []).map(([x, y], i) => (
                <circle key={i} cx={x} cy={y} r={0.55} className="echo-creature__catch" />
              ))}
            </g>
          </g>
        </g>
      </g>
    </svg>
  );
}

/* ------------------------------------------------------------------ dots */

const TICK = 150;
const HOP = [0, -1, -2, -2, -1, 0, 0, -1, -2, -1, 0];
const SHAKE = [0, 1, -1, 1, -1, 1, 0];

/** One frame of a mood, `t` ticks in. */
function frame(mood: CreatureMood, rows: readonly string[], t: number, walk: { x: number; dir: 1 | -1 }): { dots: Dot[]; cols: number; rows: number } {
  const open = gridOf(rows);
  const { cols, rows: height } = screenFor(open);
  const w = open[0]?.length ?? 0;
  const home = Math.floor((cols - w) / 2);
  const ground = height - open.length - 1;
  const blinking = t % 26 === 0;
  let pose = open;
  let x = home;
  let y = ground;
  const extra: Dot[] = [];
  if (mood === "idle") {
    pose = blinking ? shut(open) : open;
  } else if (mood === "busy") {
    if (t > 0) {
      walk.x += walk.dir;
      if (walk.x <= 1 || walk.x >= cols - w - 1) walk.dir = walk.dir === 1 ? -1 : 1;
    }
    x = walk.x;
    y = ground - (t % 2);
    pose = look(open, walk.dir);
  } else if (mood === "done") {
    y = ground + (t < HOP.length ? HOP[t]! : 0);
    pose = t >= HOP.length && blinking ? shut(open) : open;
    if (t < HOP.length && t % 2 === 1) {
      extra.push(...mark(MARKS.spark, home - 4, 1, cols, height), ...mark(MARKS.spark, home + w + 1, 2, cols, height));
    }
  } else if (mood === "error") {
    x = home + (t < SHAKE.length ? SHAKE[t]! : 0);
    pose = look(open, -1);
    if (t % 4 !== 3) extra.push(...mark(MARKS.question, home + w + 1, 0, cols, height));
  } else {
    pose = shut(open);
    const rise = Math.floor(t / 4) % 3;
    extra.push(...mark(MARKS.z, home + w, 2 - rise, cols, height));
  }
  return { dots: [...place(pose, x, y, cols, height), ...extra], cols, rows: height };
}

/** Where a frame stands still, for reduced motion: the mood's pose, its mark, no movement. */
function still(mood: CreatureMood, rows: readonly string[]) {
  return frame(mood === "busy" ? "idle" : mood, rows, mood === "done" ? HOP.length : mood === "idle" ? 1 : 2, { x: 0, dir: 1 });
}

function DotCreature({ mood, character }: { mood: CreatureMood; character: CreatureCharacter }) {
  const canvas = useRef<HTMLCanvasElement>(null);
  const reduced = useReducedMotionRef();

  useEffect(() => {
    const el = canvas.current;
    const ctx = el?.getContext("2d");
    if (!el || !ctx) return;
    const rows = character.dots ?? rasterize(character, 20);
    const inks = () => {
      const css = getComputedStyle(el);
      const forced = window.matchMedia?.("(forced-colors: active)").matches;
      return {
        body: forced ? "CanvasText" : css.getPropertyValue("--echo-accent-glow").trim() || "CanvasText",
        eye: forced ? "CanvasText" : css.getPropertyValue("--echo-text").trim() || "CanvasText",
        ghost: css.getPropertyValue("--echo-text").trim() || "CanvasText",
        glow: forced ? "transparent" : css.getPropertyValue("--echo-lcd-glow").trim() || "transparent",
      };
    };
    const P = 10;
    const draw = (f: ReturnType<typeof frame>) => {
      if (el.width !== f.cols * P) el.width = f.cols * P;
      if (el.height !== f.rows * P) el.height = f.rows * P;
      const ink = inks();
      ctx.clearRect(0, 0, el.width, el.height);
      // The dark dots under the glass, then the lit ones.
      ctx.globalAlpha = 0.06;
      ctx.fillStyle = ink.ghost;
      for (let y = 0; y < f.rows; y++) for (let x = 0; x < f.cols; x++) ctx.fillRect(x * P + 1.5, y * P + 1.5, P - 3, P - 3);
      ctx.globalAlpha = 1;
      for (const d of f.dots) {
        ctx.fillStyle = d.ink === "body" ? ink.body : ink.eye;
        ctx.shadowColor = d.ink === "body" ? ink.glow : "transparent";
        ctx.shadowBlur = d.ink === "body" ? 6 : 0;
        ctx.fillRect(d.x * P + 1.5, d.y * P + 1.5, P - 3, P - 3);
      }
      ctx.shadowBlur = 0;
    };
    if (reduced.current) {
      draw(still(mood, rows));
      return;
    }
    let t = 0;
    const walk = { x: 0, dir: 1 as 1 | -1 };
    const first = frame(mood, rows, 0, walk);
    walk.x = Math.floor((first.cols - (gridOf(rows)[0]?.length ?? 0)) / 2);
    let visible = true;
    const seen = new IntersectionObserver(([entry]) => {
      visible = entry?.isIntersecting ?? true;
    });
    seen.observe(el);
    draw(frame(mood, rows, t, walk));
    const id = window.setInterval(() => {
      if (!visible) return;
      t++;
      draw(frame(mood, rows, t, walk));
    }, TICK);
    return () => {
      window.clearInterval(id);
      seen.disconnect();
    };
  }, [mood, character, reduced]);

  return (
    <span className="echo-creature__screen">
      <canvas ref={canvas} className="echo-creature__dots" />
    </span>
  );
}

/**
 * Creature. The body is the accent's molded plastic, lit from the key light's
 * side; the eyes are paper, the pupils the seam. On a screen, it's lit dots
 * over dark ones. Composes var(--echo-*) — no hex literals; the only fixed
 * values are the single-key-light model.
 */
.echo-creature {
  --creature-size: 96px;
  display: inline-flex;
  block-size: var(--creature-size);
  max-inline-size: 100%;
  vertical-align: middle;
}

/* vector */
.echo-creature__svg {
  display: block;
  block-size: 100%;
  inline-size: auto;
  max-inline-size: 100%;
  aspect-ratio: var(--creature-ratio, 1);
  overflow: visible;
}
.echo-creature__light {
  stop-color: var(--echo-accent-highlight);
}
.echo-creature__mid {
  stop-color: var(--echo-accent);
}
.echo-creature__deep {
  stop-color: var(--echo-accent-pressed);
}
/* The one highlight the key light puts on it, top left. */
.echo-creature__gloss-in {
  stop-color: rgb(255 255 255 / calc(0.5 * var(--echo-gloss, 1)));
}
.echo-creature__gloss-out {
  stop-color: rgb(255 255 255 / calc(0 * var(--echo-gloss, 1)));
}
.echo-creature__rim {
  fill: none;
  stroke: var(--echo-accent-pressed);
  stroke-width: 0.7;
  stroke-opacity: 0.6;
}
.echo-creature__eye {
  fill: var(--echo-text);
}
.echo-creature__pupil {
  fill: var(--echo-seam);
}
.echo-creature__catch {
  fill: rgb(255 255 255 / calc(0.8 * var(--echo-gloss, 1)));
}

/* dots: its own screen */
.echo-creature__screen {
  display: inline-flex;
  box-sizing: border-box;
  block-size: 100%;
  padding: var(--echo-space-4);
  border-radius: var(--echo-radius-lg);
  background: linear-gradient(160deg, var(--echo-well) 0%, var(--echo-lcd) 100%);
  box-shadow: var(
    --echo-shadow-well-screen,
    inset 0 2px 6px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.8 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1)))
  );
}
.echo-creature__dots {
  display: block;
  block-size: 100%;
  inline-size: auto;
  max-inline-size: 100%;
}

@media (forced-colors: active) {
  .echo-creature__svg path {
    forced-color-adjust: none;
  }
  .echo-creature__svg path[fill] {
    fill: Canvas;
  }
  .echo-creature__rim {
    stroke: CanvasText;
    stroke-opacity: 1;
  }
  .echo-creature__eye {
    fill: Canvas;
    stroke: CanvasText;
    stroke-width: 0.5;
  }
  .echo-creature__pupil {
    fill: CanvasText;
  }
  .echo-creature__catch {
    fill: Canvas;
  }
  .echo-creature__screen {
    border: var(--echo-border-hairline, 1px) solid CanvasText;
  }
}

/**
 * What a creature is drawn from. Pure data: no React, no DOM.
 *
 * A character is one drawing in two forms. The vector form is paths: a body,
 * the whites of its eyes, its pupils. The dot form is rows of text, for the
 * dot matrix of a screen:
 *
 *   #  body       lit in the accent
 *   o  eye white  lit in paper
 *   *  pupil      dark
 *   .  nothing    dark
 *
 * Echo supplies the materials (the body is the accent's molded plastic, the
 * whites are paper, the pupils are the seam), so a character never carries a
 * colour of its own and relights with every theme.
 */

export interface CreatureCharacter {
  /** The drawing's viewBox. */
  viewBox: string;
  /** The body: one path, or several. */
  body: string | readonly string[];
  /** The whites of the eyes. They close toward `eyeLine` when it blinks. */
  eyes?: readonly string[];
  /** The pupils, over the whites. They follow the pointer. */
  pupils?: readonly string[];
  /** Small catch-lights on the pupils, as [x, y] points. */
  catchLights?: readonly (readonly [number, number])[];
  /** Where it breathes from and sways about: near the bottom of the body. */
  origin: readonly [number, number];
  /** The eyes' height: what a blink closes toward. */
  eyeLine: number;
  /** The same character in dots. Left out, it's drawn from the paths. */
  dots?: readonly string[];
}

/*
 * Echo itself. These are the canonical vectors, one drawing for the creature,
 * the logo's O and the boot reveal; the silhouette and the eyes are never
 * altered, only filled. Two knots of tracing noise at the right and top-right
 * notches, which a rim stroke drew as burrs, are each the single step they
 * amounted to (BUG-95); no point of the silhouette moved.
 */
export const ECHO_VIEWBOX = "102.5 4 56 56";
export const ECHO_BODY =
  "m148 24.6-0.1-0.5c2-5.1-1.8-11.7-8.1-11.8-1 0-2 0.1-2.4 0.3l-0.1 0.1c-1.2-2.6-3.9-5-8.2-5-2.7 0-5.8 1.6-7.5 5-2-0.4-6.1-1.8-10.1 3.1-1.7 2.1-2.4 5.4-1.2 8.4l-2.2 1.4c-1.1 1-2.8 3.2-2.9 5.8-0.2 4 1.9 7 5.1 8.2-1.6 3.9-0.2 9 4.9 11 1.7 0.7 3.9 0.8 6.3 0 1.2 2.7 4 5 7.6 5 3.2 0.1 6.5-1.3 8.2-5 0.7 0.2 1.8 0.5 3.4 0.5 5.2-0.1 9.2-5.4 7.2-11.1 6.7-2.5 7.6-12.3 0.1-15.4z";
export const ECHO_EYE_WHITE_L =
  "m123.6 25.8h-2.2c-2.1 0-4 1.8-4 4.1v4.2c0 2 1.4 3.8 3.6 3.8h2.6c2.5 0 3.9-1.8 3.9-3.9v-3.9c0-2.2-1.6-4.3-3.9-4.3z";
export const ECHO_EYE_WHITE_R =
  "m137.4 25.8h-2.2c-2.2 0-4.2 1.5-4.3 3.8l-0.1 4.4c0.1 2 1.4 3.9 3.7 3.9h2.9c1.8-0.1 3.7-1.4 4-3.3v-4.5c0-2.1-1.8-4.2-4-4.3z";
export const ECHO_PUPIL_L =
  "m125.5 27.7h-1.1c-1.2 0-2 0.9-2 2.2v4.8c0 1.3 0.9 2 2 2h1.1c1.3 0 2-0.6 2-2v-4.7c0-1.3-0.4-2.4-2-2.3z";
export const ECHO_PUPIL_R =
  "m139 27.7h-0.9c-1.6-0.1-2 0.9-2 2.2v4.8c0.1 1.5 0.9 2 2 2h1c1.8-0.1 2.2-1.1 2.3-2.2v-4.3c0-1.5-0.6-2.5-2.4-2.5z";
/** Vertical centre of the eyes: the blink closes toward it. */
export const ECHO_EYE_CY = 32;
export const ECHO_EYE_CATCH = [
  [123.9, 29.4],
  [137.5, 29.4],
] as const;

/**
 * Echo in dots: the silhouette sampled at 22 × 22 by how much of each dot
 * the body covers, so its eight petals keep their lobes on a screen.
 */
export const ECHO_DOTS = [
  ".........####.........",
  "........######........",
  "....#############.....",
  "...################...",
  "..#################...",
  "..##################..",
  "..##################..",
  "..##################..",
  ".######oo####oo######.",
  "######oo**##oo**#####.",
  "######oo**##oo**######",
  "######oo**##oo**######",
  "######oo**##oo**######",
  ".#####oooo##oooo#####.",
  "..##################..",
  "..##################..",
  "..##################..",
  "..#################...",
  "...################...",
  "....##############....",
  "........######........",
  ".........####.........",
] as const;

/** Echo, the creature the library is named for. */
export const echo: CreatureCharacter = {
  viewBox: ECHO_VIEWBOX,
  body: ECHO_BODY,
  eyes: [ECHO_EYE_WHITE_L, ECHO_EYE_WHITE_R],
  pupils: [ECHO_PUPIL_L, ECHO_PUPIL_R],
  catchLights: ECHO_EYE_CATCH,
  origin: [129, 38],
  eyeLine: ECHO_EYE_CY,
  dots: ECHO_DOTS,
};

/**
 * A creature on a dot-matrix screen. Pure: no React, no DOM, so what each
 * frame lights can be tested on its own.
 *
 * A character's dots are rows of text (see character.ts): `#` body, `o` eye
 * white, `*` pupil, `.` nothing. A frame is the character in a pose (eyes
 * open or shut, looking one way), placed on the screen's grid, with the few
 * marks a mood adds beside it: a question mark, a Z, a spark.
 */

export type DotInk = "body" | "eye";

/** One lit dot on the screen. Dark dots aren't listed: the grid is dark. */
export interface Dot {
  x: number;
  y: number;
  ink: DotInk;
}

/** The rows as a grid of characters, every row padded to the widest. */
export function gridOf(rows: readonly string[]): string[][] {
  const width = Math.max(0, ...rows.map((r) => r.length));
  return rows.map((r) => r.padEnd(width, ".").split(""));
}

const isEye = (c: string) => c === "o" || c === "*";

/** The rows the eyes are on, top to bottom. */
function eyeRows(grid: string[][]): number[] {
  return grid.flatMap((row, y) => (row.some(isEye) ? [y] : []));
}

/**
 * Eyes shut: the whites and pupils close into one line of white across the
 * middle of where the eyes were, the rest of them body.
 */
export function shut(grid: string[][]): string[][] {
  const rows = eyeRows(grid);
  if (rows.length === 0) return grid;
  const line = rows[Math.floor((rows.length - 1) / 2) + (rows.length > 2 ? 1 : 0)]!;
  return grid.map((row, y) => row.map((c) => (isEye(c) ? (y === line ? "o" : "#") : c)));
}

/**
 * Eyes looking left (-1), ahead (0) or right (1): in each run of white on a
 * row, the pupils move to that side of it.
 */
export function look(grid: string[][], dir: -1 | 0 | 1): string[][] {
  return grid.map((row) => {
    const out = [...row];
    let x = 0;
    while (x < out.length) {
      if (!isEye(out[x]!)) {
        x++;
        continue;
      }
      let end = x;
      while (end < out.length && isEye(out[end]!)) end++;
      const run = out.slice(x, end);
      const pupils = run.filter((c) => c === "*").length;
      if (pupils > 0 && pupils < run.length) {
        const at = dir === -1 ? 0 : dir === 1 ? run.length - pupils : Math.floor((run.length - pupils) / 2);
        for (let i = 0; i < run.length; i++) out[x + i] = i >= at && i < at + pupils ? "*" : "o";
      }
      x = end;
    }
    return out;
  });
}

/** The lit dots of a grid placed at (ox, oy) on a screen, clipped to it. */
export function place(grid: string[][], ox: number, oy: number, cols: number, rows: number): Dot[] {
  const dots: Dot[] = [];
  grid.forEach((row, y) =>
    row.forEach((c, x) => {
      const sx = ox + x;
      const sy = oy + y;
      if (sx < 0 || sy < 0 || sx >= cols || sy >= rows) return;
      if (c === "#") dots.push({ x: sx, y: sy, ink: "body" });
      else if (c === "o") dots.push({ x: sx, y: sy, ink: "eye" });
    }),
  );
  return dots;
}

/** Marks a mood draws beside the creature, in paper. */
export const MARKS = {
  question: ["###", "..#", ".##", "...", ".#."],
  z: ["###", "..#", ".#.", "#..", "###"],
  spark: [".#.", "###", ".#."],
} as const;

/** A mark's lit dots at (ox, oy). */
export function mark(rows: readonly string[], ox: number, oy: number, cols: number, screenRows: number): Dot[] {
  return place(gridOf(rows).map((r) => r.map((c) => (c === "#" ? "o" : "."))), ox, oy, cols, screenRows);
}

/** The screen a character needs: room to walk each side and to hop and dream above it. */
export function screenFor(grid: string[][]): { cols: number; rows: number } {
  const w = grid[0]?.length ?? 0;
  return { cols: w + 14, rows: grid.length + 7 };
}

/**
 * A character's paths turned into dots, for one that doesn't bring its own.
 * Each dot is lit by how much of it the shape covers (sampled 4 × 4), so
 * lobes and notches survive at a screen's resolution. Browser only: it asks
 * the canvas whether points are inside the paths.
 */
import type { CreatureCharacter } from "./character";

const list = (d: string | readonly string[] | undefined) => (d === undefined ? [] : typeof d === "string" ? [d] : d);

export function rasterize(character: CreatureCharacter, size: number): string[] {
  const ctx = document.createElement("canvas").getContext("2d");
  if (!ctx) return [];
  const [vx = 0, vy = 0, vw = 1, vh = 1] = character.viewBox.split(/[\s,]+/).map(Number);
  const body = list(character.body).map((d) => new Path2D(d));
  const eyes = list(character.eyes).map((d) => new Path2D(d));
  const pupils = list(character.pupils).map((d) => new Path2D(d));
  const inside = (paths: Path2D[], x: number, y: number) => paths.some((p) => ctx.isPointInPath(p, x, y));
  const cell = Math.max(vw, vh) / size;
  const rows: string[] = [];
  for (let j = 0; j < size; j++) {
    let row = "";
    for (let i = 0; i < size; i++) {
      const cx = vx + (i + 0.5) * cell;
      const cy = vy + (j + 0.5) * cell;
      if (inside(pupils, cx, cy)) row += "*";
      else if (inside(eyes, cx, cy)) row += "o";
      else {
        let covered = 0;
        for (let a = 0; a < 4; a++)
          for (let b = 0; b < 4; b++) if (inside(body, vx + (i + (a + 0.5) / 4) * cell, vy + (j + (b + 0.5) / 4) * cell)) covered++;
        row += covered >= 10 ? "#" : ".";
      }
    }
    rows.push(row);
  }
  // Drop empty rows and columns round the drawing.
  const used = rows.filter((r) => r.includes("#") || r.includes("o"));
  const first = Math.min(...used.map((r) => r.search(/[^.]/)));
  const last = Math.max(...used.map((r) => r.length - 1 - [...r].reverse().join("").search(/[^.]/)));
  return used.map((r) => r.slice(first, last + 1));
}

/**
 * The creature rig: the living layers every creature shares.
 *
 * Built once for a creature's whole life, never torn down on a change of mood:
 * a mood is a set of targets (how far it drifts, how deep it breathes, how
 * open the lids are, where the eyes look), and every one of them is on a
 * spring, so a change of mood is a change of direction from wherever the
 * creature is (BUG-96: tearing the tweens down snapped it back to centre).
 *
 * Each layer is its own SVG group, so the layers compose instead of fighting
 * over one transform:
 *   drift   continuous wander + lean toward the pointer (never stops: layered
 *           slow sines, whose phases advance with the pace, so a slower mood
 *           slows them without a jump)
 *   breath  a slow scale about the body's low centre
 *   lids    the eyes' open-ness, a blink riding on top
 *   pupils  where the eyes look: the pointer, a glance, or a resting point
 *
 * Eyes lead and the body follows: the pupils are on a quick spring, the lean
 * on a slow one. One pointer listener serves every creature on the page, and
 * each measures its box once per frame, only when the pointer or the page has
 * moved, before any creature writes. A creature out of view stops drawing.
 */
import gsap from "gsap";
import { createSpring, type Spring, type SpringConfig } from "echo-ui-core/tactile";

/** How far the pupils may travel, viewBox units: they stay inside the whites. */
export const TRAVEL = 1.25;

export interface RigMood {
  /** Wander, viewBox units, and sway, degrees. */
  drift: number;
  sway: number;
  /** The wander's pace: 1 is the watching pace. */
  pace: number;
  /** How far the body leans toward the pointer, units; 0 doesn't lean. */
  lean: number;
  /** How much bigger at the top of a breath (0.03 = 3%), and seconds per breath. */
  breath: number;
  breathPeriod: number;
  /** 1 open, 0.52 drowsy, 0.06 asleep. */
  lids: number;
  /** Follow the pointer and glance round when it's still; rest at `rest`; or let the caller steer. */
  look: "follow" | "rest" | "held";
  /** Where resting eyes settle, in units of TRAVEL. */
  rest?: readonly [number, number];
  /** Seconds between blinks, or null to never blink. */
  blink: readonly [number, number] | null;
}

export interface RigEls {
  /** The creature's box: where the pointer is measured from. */
  wrap: HTMLElement;
  drift: SVGGElement;
  breath: SVGGElement;
  lids: SVGGElement;
  pupils: SVGGElement;
}

export interface Rig {
  /** Head for a new mood from wherever the creature is. */
  set(mood: RigMood): void;
  /** Point the eyes (units of TRAVEL) when the mood's look is "held". */
  look(x: number, y: number): void;
  /** One blink now (and sometimes two). */
  blink(twice?: boolean): void;
  /** A little hop, or two: it's pleased. */
  hop(times?: number): void;
  /** A quick side-to-side: something's wrong. */
  shake(): void;
  destroy(): void;
}

/* --- the shared pointer ------------------------------------------------- */

const pointer = { x: 0, y: 0, at: -Infinity };
const live = new Set<{ measure(): void }>();
let stale = true;

const moved = (e: PointerEvent) => {
  pointer.x = e.clientX;
  pointer.y = e.clientY;
  pointer.at = performance.now();
  stale = true;
};
const shifted = () => {
  stale = true;
};
/** Runs first on every tick: all the reads, before any creature writes. */
const measureAll = () => {
  if (!stale) return;
  stale = false;
  for (const r of live) r.measure();
};

function join(r: { measure(): void }) {
  if (live.size === 0) {
    window.addEventListener("pointermove", moved, { passive: true });
    window.addEventListener("scroll", shifted, { passive: true, capture: true });
    window.addEventListener("resize", shifted);
    gsap.ticker.add(measureAll, false, true);
  }
  live.add(r);
  stale = true;
}

function leave(r: { measure(): void }) {
  live.delete(r);
  if (live.size > 0) return;
  window.removeEventListener("pointermove", moved);
  window.removeEventListener("scroll", shifted, { capture: true });
  window.removeEventListener("resize", shifted);
  gsap.ticker.remove(measureAll);
}

/* --- the rig ------------------------------------------------------------- */

const SETTLE: SpringConfig = { duration: 0.9, bounce: 0 };
const EYES: SpringConfig = { duration: 0.22, bounce: 0.08 };
const LEAN: SpringConfig = { duration: 1.1, bounce: 0 };
const LIDS: SpringConfig = { duration: 0.8, bounce: 0 };
const PERK: SpringConfig = { duration: 0.34, bounce: 0.35 };
const JOLT: SpringConfig = { duration: 0.16, bounce: 0.2 };
/** The pointer counts as present this long after it last moved, ms. */
const PRESENT = 2200;

/** Slow sines, in radians per second at pace 1: periods of 7–13 s, none a multiple of another. */
const WANDER = [0.83, 0.53, 0.71, 0.47, 0.61, 0.89] as const;

export function createRig(
  els: RigEls,
  opts: {
    /** The body's low centre: the breath and sway pivot. */
    origin: readonly [number, number];
    /** The eyes' centre: the blink pivot. */
    eye: readonly [number, number];
    mood: RigMood;
  },
): Rig {
  let mood = opts.mood;
  const [ox, oy] = opts.origin;
  const [, ey] = opts.eye;
  const spring = (v: number, cfg = SETTLE) => createSpring(v, cfg, () => undefined);

  const s = {
    drift: spring(mood.drift),
    sway: spring(mood.sway),
    pace: spring(mood.pace),
    breath: spring(mood.breath),
    breathPeriod: spring(mood.breathPeriod),
    lids: spring(mood.lids, LIDS),
    leanX: spring(0, LEAN),
    leanY: spring(0, LEAN),
    px: spring((mood.rest?.[0] ?? 0) * TRAVEL, EYES),
    py: spring((mood.rest?.[1] ?? 0) * TRAVEL, EYES),
    perk: spring(0, PERK),
    jolt: spring(0, JOLT),
  } satisfies Record<string, Spring>;
  const blinkLid = { v: 1 };

  // Start the wander somewhere different for each creature, so two never move in step.
  const phase = WANDER.map(() => Math.random() * Math.PI * 2);
  let breathPhase = Math.random() * Math.PI * 2;

  let rect: DOMRect | null = null;
  let visible = true;
  const self = {
    measure() {
      if (visible) rect = els.wrap.getBoundingClientRect();
    },
  };
  join(self);

  const seen = new IntersectionObserver(([entry]) => {
    visible = entry?.isIntersecting ?? true;
    if (visible) stale = true;
  });
  seen.observe(els.wrap);

  /* Eyes: follow the pointer, or glance round on their own when it's still. */
  let glance: gsap.core.Tween | null = null;
  const glanceSoon = () => {
    glance?.kill();
    glance = gsap.delayedCall(gsap.utils.random(1.6, 3.2), () => {
      if (mood.look === "follow" && performance.now() - pointer.at > PRESENT) {
        s.px.to(gsap.utils.random(-0.7, 0.7) * TRAVEL);
        s.py.to(gsap.utils.random(-0.3, 0.5) * TRAVEL);
      }
      glanceSoon();
    });
  };
  glanceSoon();

  /* Blinks: now and then, with the occasional double. */
  let blinking: gsap.core.Timeline | null = null;
  let nextBlink: gsap.core.Tween | null = null;
  const blink = (twice = Math.random() < 0.2) => {
    blinking?.kill();
    blinking = gsap.timeline();
    for (let i = 0; i < (twice ? 2 : 1); i++) {
      blinking
        .to(blinkLid, { v: 0.08, duration: 0.06, ease: "power2.in" })
        .to(blinkLid, { v: 1, duration: 0.1, ease: "power2.out" });
    }
  };
  const blinkSoon = () => {
    nextBlink?.kill();
    if (!mood.blink) return;
    nextBlink = gsap.delayedCall(gsap.utils.random(mood.blink[0], mood.blink[1]), () => {
      blink();
      blinkSoon();
    });
  };
  blinkSoon();

  const tick = (_time: number, deltaMs: number) => {
    if (!visible) return;
    const dt = Math.min(deltaMs, 64) / 1000;
    const pace = s.pace.value;
    for (let k = 0; k < phase.length; k++) phase[k]! += WANDER[k]! * pace * dt;
    breathPhase += ((Math.PI * 2) / Math.max(0.5, s.breathPeriod.value)) * dt;

    // Where the pointer is, relative to the creature (a unit circle round its eyes).
    const present = rect !== null && performance.now() - pointer.at < PRESENT;
    let nx = 0;
    let ny = 0;
    if (present && rect) {
      nx = (pointer.x - (rect.left + rect.width / 2)) / (rect.width / 2);
      ny = (pointer.y - (rect.top + rect.height * 0.44)) / (rect.height / 2);
      const m = Math.hypot(nx, ny);
      if (m > 1) {
        nx /= m;
        ny /= m;
      }
    }
    if (mood.look === "follow" && present) {
      s.px.to(nx * TRAVEL);
      s.py.to(ny * TRAVEL * 0.8);
    }
    const lean = present ? mood.lean : 0;
    s.leanX.to(nx * lean);
    s.leanY.to(ny * lean * 0.5);

    const a = s.drift.value;
    const r = s.sway.value;
    const x = a * (0.6 * Math.sin(phase[0]!) + 0.4 * Math.sin(phase[1]! + 1.3)) + s.leanX.value + s.jolt.value;
    const y = a * (0.55 * Math.sin(phase[2]!) + 0.45 * Math.sin(phase[3]! + 0.7)) + s.leanY.value + s.perk.value;
    const rot = r * (0.6 * Math.sin(phase[4]!) + 0.4 * Math.sin(phase[5]! + 2.1)) + s.leanX.value * 0.6;
    els.drift.setAttribute("transform", `translate(${x.toFixed(3)} ${y.toFixed(3)}) rotate(${rot.toFixed(3)} ${ox} ${oy})`);

    const b = 1 + s.breath.value * (0.5 - 0.5 * Math.cos(breathPhase));
    els.breath.setAttribute("transform", `translate(${ox} ${oy}) scale(${b.toFixed(4)}) translate(${-ox} ${-oy})`);

    // Heavy lids also sit a little lower, the way a sleepy face droops.
    const lid = Math.max(0.02, s.lids.value * blinkLid.v);
    const droop = Math.max(0, (0.52 - s.lids.value) / 0.46) * 1.4;
    els.lids.setAttribute("transform", `translate(0 ${(ey + droop).toFixed(3)}) scale(1 ${lid.toFixed(4)}) translate(0 ${-ey})`);
    els.pupils.setAttribute("transform", `translate(${s.px.value.toFixed(3)} ${s.py.value.toFixed(3)})`);
  };
  gsap.ticker.add(tick);

  const rig: Rig = {
    set(next) {
      const waking = next.lids > mood.lids + 0.3;
      mood = next;
      s.drift.to(next.drift);
      s.sway.to(next.sway);
      s.pace.to(next.pace);
      s.breath.to(next.breath);
      s.breathPeriod.to(next.breathPeriod);
      s.lids.to(next.lids);
      if (next.look === "rest") {
        s.px.to((next.rest?.[0] ?? 0) * TRAVEL);
        s.py.to((next.rest?.[1] ?? 0) * TRAVEL);
      }
      if (waking) {
        // Waking up: a small perk, and a double blink once the lids are open.
        s.perk.to(-1.1);
        gsap.delayedCall(0.14, () => s.perk.to(0));
        gsap.delayedCall(0.45, () => blink(true));
      }
      blinkSoon();
    },
    look(x, y) {
      s.px.to(x * TRAVEL);
      s.py.to(y * TRAVEL);
    },
    blink,
    hop(times = 2) {
      for (let i = 0; i < times; i++) {
        gsap.delayedCall(i * 0.36, () => s.perk.to(-3.2));
        gsap.delayedCall(i * 0.36 + 0.15, () => s.perk.to(0));
      }
    },
    shake() {
      [1.4, -1.4, 1, -0.8, 0].forEach((to, i) => gsap.delayedCall(i * 0.07, () => s.jolt.to(to)));
    },
    destroy() {
      gsap.ticker.remove(tick);
      seen.disconnect();
      leave(self);
      glance?.kill();
      nextBlink?.kill();
      blinking?.kill();
      Object.values(s).forEach((sp) => sp.stop());
    },
  };
  return rig;
}

/** The one frame reduced motion shows: lids at the mood, eyes at rest, nothing moving. */
export function stillPose(els: Omit<RigEls, "wrap">, opts: { eye: readonly [number, number]; mood: RigMood }) {
  const [, ey] = opts.eye;
  const lids = opts.mood.lids;
  const droop = Math.max(0, (0.52 - lids) / 0.46) * 1.4;
  els.drift.removeAttribute("transform");
  els.breath.removeAttribute("transform");
  els.lids.setAttribute("transform", `translate(0 ${ey + droop}) scale(1 ${lids}) translate(0 ${-ey})`);
  const [rx, ry] = opts.mood.look === "rest" ? (opts.mood.rest ?? [0, 0]) : [0, 0];
  els.pupils.setAttribute("transform", `translate(${rx * TRAVEL} ${ry * TRAVEL})`);
}

